do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int;
begin
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Deliveroo$q$,$q$public_company$q$),($q$Delivery Hero$q$,$q$public_company$q$),($q$Olo$q$,$q$public_company$q$),($q$PayPal$q$,$q$public_company$q$),($q$Prosus$q$,$q$public_company$q$),($q$SevenRooms$q$,$q$private_company$q$),($q$Stripe$q$,$q$private_company$q$),($q$Symbiosys$q$,$q$private_company$q$),($q$Wolt$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$As discussed in Note 4 to the consolidated financial statements, on October 2, 2025, the Company acquired Deliveroo plc (Deliveroo) in a business combination for $3,724 million.$q$),(2,$q$Globally, we compete with other local on-demand delivery companies, including Amazon, Uber Eats, Prosus, Delivery Hero, and other local incumbents.$q$),(3,$q$On June 13, 2025, the Company completed the acquisition of 100 percent of the outstanding equity interests of SevenRooms Inc. (“SevenRooms”)$q$),(4,$q$On May 28, 2025, the Company acquired Symbiosys Corp. (“Symbiosys”), a retail media platform company, to expand offsite advertising capabilities.$q$),(5,$q$On May 6, 2025, the Company issued an announcement (the “Rule 2.7 Announcement”) pursuant to Rule 2.7 of the UK City Code on Takeovers and Mergers (the "Code"), disclosing that the board of directors of the Company and the board of directors of Deliveroo, a company incorporated in England and Wales, had reached agreement on the terms of a recommended final cash offer by the Company for the entire issued and to be issued share capital of Deliveroo (the "Deliveroo Transaction").$q$),(6,$q$On October 2, 2025, the Company completed the acquisition of substantially all of the outstanding equity interests of Deliveroo plc (“Deliveroo”), which was accounted for under the acquisition method of accounting.$q$),(7,$q$The Company granted restricted stock to certain continuing employees in connection with the acquisition of Wolt Enterprises Oy on May 31, 2022.$q$),(8,$q$We also have integrations with or otherwise utilize or rely on PayPal, Stripe, Olo, Google Maps, Amazon Web Services ("AWS"), and a variety of other third-party vendors.$q$),(9,$q$We primarily host our platform and support our operations on data centers provided by AWS, a third-party provider of cloud infrastructure services, in a limited number of locations.$q$),(10,$q$We primarily rely on a third-party payment processor, Stripe, to process payments made to merchants and Dashers and third-party payment processors to process payments made by consumers, primarily Stripe and PayPal.$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$competes$q$,$q$DASH$q$,$q$Amazon$q$,$q${2}$q$::int[],$q${business}$q$::text[],null,null,null,null),(2,$q$competes$q$,$q$DASH$q$,$q$Uber Eats$q$,$q${2}$q$::int[],$q${business}$q$::text[],null,null,null,null),(3,$q$competes$q$,$q$DASH$q$,$q$Prosus$q$,$q${2}$q$::int[],$q${business}$q$::text[],null,null,null,null),(4,$q$competes$q$,$q$DASH$q$,$q$Delivery Hero$q$,$q${2}$q$::int[],$q${business}$q$::text[],null,null,null,null),(5,$q$supplies$q$,$q$Stripe$q$,$q$DASH$q$,$q${10}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(6,$q$supplies$q$,$q$PayPal$q$,$q$DASH$q$,$q${10}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(7,$q$supplies$q$,$q$Olo$q$,$q$DASH$q$,$q${8}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(8,$q$supplies$q$,$q$Alphabet$q$,$q$DASH$q$,$q${8}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(9,$q$supplies$q$,$q$Amazon$q$,$q$DASH$q$,$q${9}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(10,$q$acquires$q$,$q$DASH$q$,$q$Deliveroo$q$,$q${1,6,5}$q$::int[],$q${notes,notes,notes}$q$::text[],null,null,null,null),(11,$q$acquires$q$,$q$DASH$q$,$q$SevenRooms$q$,$q${3}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(12,$q$acquires$q$,$q$DASH$q$,$q$Symbiosys$q$,$q${4}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(13,$q$acquires$q$,$q$DASH$q$,$q$Wolt$q$,$q${7}$q$::int[],$q${notes}$q$::text[],null,null,null,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Amazon$q$ then ticker=$q$AMZN$q$ when $q$Alphabet$q$ then ticker=$q$GOOGL$q$ when $q$Microsoft$q$ then ticker=$q$MSFT$q$ when $q$NVIDIA$q$ then ticker=$q$NVDA$q$ when $q$Intel$q$ then ticker=$q$INTC$q$ when $q$Oracle$q$ then ticker=$q$ORCL$q$ when $q$AMD$q$ then ticker=$q$AMD$q$ when $q$CoreWeave$q$ then ticker=$q$CRWV$q$ when $q$TSMC$q$ then ticker=$q$TSM$q$ when $q$Tesla$q$ then ticker=$q$TSLA$q$ when $q$Uber Eats$q$ then ticker=$q$UBER$q$ when $q$Uber$q$ then ticker=$q$UBER$q$ when $q$Uber Technologies$q$ then ticker=$q$UBER$q$ when $q$Grab$q$ then ticker=$q$GRAB$q$ when $q$DoorDash$q$ then ticker=$q$DASH$q$ when $q$Instacart$q$ then ticker=$q$CART$q$ when $q$Applied Digital$q$ then ticker=$q$APLD$q$ when $q$Meta Platforms$q$ then ticker=$q$META$q$ when $q$Apple$q$ then ticker=$q$AAPL$q$ when $q$Palantir Technologies$q$ then ticker=$q$PLTR$q$ when $q$Lucid$q$ then ticker=$q$LCID$q$ when $q$Lucid Group$q$ then ticker=$q$LCID$q$ when $q$Nebius Group$q$ then ticker=$q$NBIS$q$ when $q$Cloudflare$q$ then ticker=$q$NET$q$ when $q$Lyft$q$ then ticker=$q$LYFT$q$ when $q$Google Maps$q$ then ticker=$q$GOOGL$q$ when $q$Taiwan Semiconductor Manufacturing$q$ then ticker=$q$TSM$q$ when $q$DASH$q$ then ticker=$q$DASH$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,tokens_in,tokens_out,cost_usd,status,review_status) values ('filings_extraction','batch',$q$DASH M6 group 2-4$q$,'claude-sonnet-5-5',250502,3799,0.7623,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; end if; if (select status from public.relationships where id=rid)='staged' then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1792789/000179278926000013/dash-20251231.htm$q$,r.sec[k],t,true,$q$2026-02-18$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
